			"wiki.title": "Вики Summit Linux",
			"wiki.lead":
				"Документация сообщества о Summit Linux и пакетном менеджере picu: понятия, команды, репозитории и ответы на вопросы.",
			"wiki.secWhat": "Что такое Summit Linux",
