			"wiki.secLinks": "Ссылки",
			"wiki.whatText":
				"Summit Linux — независимый дистрибутив Linux, собранный из исходного кода по принципам Linux From Scratch: прозрачные компоненты, контролируемые сборки и минимум лишнего ПО.",
			"wiki.philoLabel": "Философия:",
			"wiki.philoText":
				"прозрачность вместо магии, рецепт вместо чёрного ящика.",
			"wiki.installNote": "Раздел в разработке — скоро будет.",
			"wiki.quickText":
				"Повседневная работа в три команды: синхронизировать индексы, поставить пакет, обновить систему.",
			"wiki.cmdText":
				"picu управляет репозиториями, рецептами сборки, бинарными пакетами, подписями, хранилищем доверия и базой пакетов.",
			"wiki.cmdSync": "— получить индексы репозиториев и проверить подписи.",
			"wiki.cmdAdd": "— установить пакет с доверенного зеркала.",
			"wiki.cmdCook": "— собрать пакет из исходников в изоляции.",
			"wiki.cmdCut": "— удалить пакет и убрать бесхозные остатки.",
			"wiki.cmdFind": "— поиск пакетов по индексам репозиториев.",
			"wiki.cmdList": "— показать установленные пакеты.",
			"wiki.cmdInfo": "— версия, рецепт и зеркало пакета.",
			"wiki.cmdUpdate": "— обновить пакеты до последних доверенных версий.",
			"wiki.cmdRebase": "— пересобрать локальный рецепт на текущем базисе.",
			"wiki.cmdTrust": "— доверенные ключи и отозванные сертификаты.",
			"wiki.mirrorsNoteLabel": "Зеркала сообщества:",
			"wiki.mirrorsNoteText":
				"требуют явного доверия — не подключайте недоверенное зеркало с небезопасными флагами на рабочей системе.",
			"wiki.faq1q": "Summit Linux готов для ежедневного использования?",
			"wiki.faq1a":
				"Проект — рабочая концепция с поэтапным планом реализации; следите за страницей новостей.",
			"wiki.faq2q": "Чем picu отличается от других менеджеров пакетов?",
			"wiki.faq2a":
				"picu сочетает рецепты из исходников и бинарные пакеты с криптографической проверкой каждого индекса репозитория.",
			"wiki.faq3q": "Какая init-система используется?",
			"wiki.faq3a": "OpenRC / sysvinit с опциональным runit.",
			"wiki.faq4q": "Как проверить загрузки?",
			"wiki.faq4a":
				"Релизы будут снабжены контрольными суммами, а индексы репозиториев будут подписаны; подробности — на странице скачивания.",
			"wiki.faq5q": "Можно ли собирать пакеты из исходников?",
			"wiki.faq5a":
				"Да — команда <code>picu cook</code> с файлом рецепта выполняет изолированную воспроизводимую сборку.",
			"wiki.faq6q": "Где полная документация?",
			"wiki.faq6a":
				'В репозитории <a href=\\"https://github.com/Summit-picu/Markdown-files-and-info\\" target=\\"_blank\\" rel=\\"noopener\\">Markdown-files-and-info</a> и на странице <a href=\\"download.html?lang=ru\\">скачивания</a>.',
			"wiki.faq7q": "Какие команды picu нужны чаще всего?",
			"wiki.faq7a":
				"<code>picu sync</code>, <code>picu add</code>, <code>picu update</code>, <code>picu find</code> и <code>picu info</code> для повседневной работы; <code>picu cook</code> и <code>picu cut</code> для сборки из исходников; <code>picu trust</code> для управления ключами.",
			"wiki.faq8q": "Как добавить зеркало сообщества?",
			"wiki.faq8a":
				"Добавьте его описание в <code>/etc/picu/mirrors.d/</code> и выдайте явное доверие — зеркала сообщества никогда не доверенные по умолчанию.",
			"wiki.faq9q": "Что делать, если проверка подписи не прошла?",
			"wiki.faq9a":
				"Ничего не ставьте: повторите <code>picu sync</code>, проверьте срок действия индекса и доверенные ключи, затем сообщите о зеркале.",
			"wiki.linksDownload": "Скачать Summit Linux",
			"wiki.linksDocs": "Репозиторий документации Markdown-files-and-info",
