			"idx.statusTitle": "概念与实施计划",
			"idx.statusText":
				"Summit Linux 是以 <code>picu</code> 为包管理器的独立 LFS/源码发行版概念。项目文档定义了信任模型、事务模型、构建隔离和分阶段实施计划。",
			"wiki.title": "Summit Linux 维基",
			"wiki.lead":
				"Summit Linux 与 picu 包管理器的社区文档：概念、命令、仓库与问答。",
			"wiki.secWhat": "什么是 Summit Linux",
			"wiki.secInstall": "安装",
			"wiki.secQuick": "快速开始",
			"wiki.secCommands": "命令",
			"wiki.secMirrors": "仓库与镜像",
			"wiki.secFaq": "常见问题",
			"wiki.secLinks": "链接",
			"wiki.whatText":
				"Summit Linux 是遵循 Linux From Scratch 原则从源码构建的独立 Linux 发行版：透明的组件、受控的构建和最小化的软件。",
			"wiki.philoLabel": "理念：",
			"wiki.philoText": "透明而非魔法，配方而非黑盒。",
			"wiki.installNote": "本节正在开发中——即将推出。",
			"wiki.quickText":
				"日常工作只需三条命令：同步索引、安装软件包、升级系统。",
			"wiki.cmdText":
				"picu 管理仓库、构建配方、二进制包、签名、信任库和软件包数据库。",
			"wiki.cmdSync": "——获取仓库索引并验证签名。",
			"wiki.cmdAdd": "——从受信镜像安装软件包。",
			"wiki.cmdCook": "——在隔离环境中从源码构建软件包。",
			"wiki.cmdCut": "——删除软件包并清理残留。",
			"wiki.cmdFind": "——在仓库索引中搜索软件包。",
			"wiki.cmdList": "——显示已安装的软件包。",
			"wiki.cmdInfo": "——显示版本、配方和镜像详情。",
			"wiki.cmdUpdate": "——升级到最新的受信版本。",
			"wiki.cmdRebase": "——基于当前基座重建本地配方。",
			"wiki.cmdTrust": "——显示受信密钥和已吊销证书。",
			"wiki.mirrorsNoteLabel": "社区镜像：",
			"wiki.mirrorsNoteText":
				"需要显式信任——切勿在生产系统上用不安全选项启用不受信镜像。",
			"wiki.faq1q": "Summit Linux 可以日常使用了吗？",
			"wiki.faq1a":
				"本项目是带有分阶段计划的工作概念；请关注新闻页获取版本信息。",
			"wiki.faq2q": "picu 与其他包管理器有何不同？",
			"wiki.faq2a":
				"picu 将源码配方与二进制包结合，并对每个仓库索引进行加密验证。",
			"wiki.faq3q": "Summit 使用哪种 init 系统？",
			"wiki.faq3a": "OpenRC / sysvinit，可选 runit 配置。",
			"wiki.faq4q": "如何验证下载？",
			"wiki.faq4a": "版本将附带校验和，仓库索引将被签名；详见下载页。",
			"wiki.faq5q": "可以从源码构建软件包吗？",
			"wiki.faq5a":
				"可以——用配方文件运行 <code>picu cook</code>，进行隔离、可复现的构建。",
			"wiki.faq6q": "完整文档在哪里？",
			"wiki.faq6a":
				'在 <a href=\\"https://github.com/Summit-picu/Markdown-files-and-info\\" target=\\"_blank\\" rel=\\"noopener\\">Markdown-files-and-info</a> 仓库和<a href=\\"download.html\\">下载</a>页。',
			"wiki.faq7q": "最常用的 picu 命令有哪些？",
			"wiki.faq7a":
				"日常用 <code>picu sync</code>、<code>picu add</code>、<code>picu update</code>、<code>picu find</code> 和 <code>picu info</code>；源码构建用 <code>picu cook</code> 和 <code>picu cut</code>；密钥管理用 <code>picu trust</code>。",
			"wiki.faq8q": "如何添加社区镜像？",
			"wiki.faq8a":
				"将其描述加入 <code>/etc/picu/mirrors.d/</code> 并显式授信——社区镜像默认不受信。",
			"wiki.faq9q": "签名校验失败怎么办？",
			"wiki.faq9a":
				"不要安装任何东西：重新运行 <code>picu sync</code>，检查索引有效期和受信密钥，然后报告该镜像。",
			"wiki.linksDownload": "下载 Summit Linux",
			"wiki.linksDocs": "Markdown-files-and-info 文档仓库",
