			"wiki.secLinks": "リンク",
			"wiki.whatText":
				"Summit LinuxはLinux From Scratchの原則でソースから構築される独立ディストリビューションです：透明なコンポーネント、管理されたビルド、最小のソフトウェア。",
			"wiki.philoLabel": "思想：",
			"wiki.philoText": "魔法ではなく透明性、ブラックボックスではなくレシピ。",
			"wiki.installNote": "この節は開発中 — 近日公開。",
			"wiki.quickText":
				"日常作業は3コマンド：インデックス同期、パッケージ導入、システム更新。",
			"wiki.cmdText":
				"picuはリポジトリ、ビルドレシピ、バイナリ、署名、信頼ストア、パッケージDBを管理します。",
			"wiki.cmdSync": "— リポジトリのインデックスを取得し署名を検証。",
			"wiki.cmdAdd": "— 信頼ミラーからパッケージを導入。",
			"wiki.cmdCook": "— 分離環境でソースからビルド。",
			"wiki.cmdCut": "— パッケージを削除し残留物を掃除。",
			"wiki.cmdFind": "— インデックスからパッケージを検索。",
			"wiki.cmdList": "— 導入済みパッケージを表示。",
			"wiki.cmdInfo": "— バージョン、レシピ、ミラー詳細を表示。",
			"wiki.cmdUpdate": "— 最新の信頼バージョンへ更新。",
			"wiki.cmdRebase": "— ローカルレシピを現行ベースで再ビルド。",
			"wiki.cmdTrust": "— 信頼鍵と失効証明書を表示。",
			"wiki.mirrorsNoteLabel": "コミュニティミラー：",
			"wiki.mirrorsNoteText":
				"明示的な信頼が必要です — 本番環境で未信頼ミラーを安全でないフラグで有効化しないでください。",
			"wiki.faq1q": "Summit Linuxは日常利用できますか？",
			"wiki.faq1a":
				"段階的計画を持つ動作中の構想です。リリースはNewsページを参照。",
			"wiki.faq2q": "picuは他の管理ツールとどう違いますか？",
			"wiki.faq2a":
				"picuはソースレシピとバイナリを組み合わせ、全インデックスを暗号学的に検証します。",
			"wiki.faq3q": "Summitのinitは？",
			"wiki.faq3a": "OpenRC / sysvinit、任意でrunit構成。",
			"wiki.faq4q": "ダウンロードを検証するには？",
			"wiki.faq4a":
				"リリースにはチェックサム、インデックスには署名が付きます。詳細はDownloadページへ。",
			"wiki.faq5q": "ソースからビルドできますか？",
			"wiki.faq5a":
				"はい — レシピファイルで<code>picu cook</code>を使い、分離・再現可能なビルドを行います。",
			"wiki.faq6q": "完全な文書はどこに？",
			"wiki.faq6a":
				'<a href=\\"https://github.com/Summit-picu/Markdown-files-and-info\\" target=\\"_blank\\" rel=\\"noopener\\">Markdown-files-and-info</a>リポジトリと<a href=\\"download.html\\">Download</a>ページにあります。',
			"wiki.faq7q": "よく使うpicuコマンドは？",
			"wiki.faq7a":
				"日常は<code>picu sync</code>、<code>picu add</code>、<code>picu update</code>、<code>picu find</code>、<code>picu info</code>。ソース用に<code>picu cook</code>と<code>picu cut</code>、鍵管理に<code>picu trust</code>。",
			"wiki.faq8q": "コミュニティミラーを追加するには？",
			"wiki.faq8a":
				"記述を<code>/etc/picu/mirrors.d/</code>に追加し明示的に信頼します — デフォルトで信頼されません。",
			"wiki.faq9q": "署名検証が失敗したら？",
			"wiki.faq9a":
				"何も導入せず、<code>picu sync</code>を再実行し、インデックス期限と信頼鍵を確認してミラーを報告してください。",
