			"abt.feat.1": "ソースファースト:LFS ツールチェーンと宣言的ビルドレシピ。",
			"abt.feat.2":
				"最小ベース:既定は CLI のみのインストール、隠れたサービスなし。",
			"abt.feat.3": "Init は選択式:OpenRC / sysvinit、任意で runit。",
			"abt.feat.4":
				"再現可能なビルド:固定フラグ、隔離されたビルド環境、ソースのチェックサム。",
			"abt.feat.5":
				"すべてに署名:リポジトリインデックス、リリース、レシピを暗号学的に検証。",
			"abt.feat.6":
				"ダウングレード保護:リポジトリメタデータのバージョン検査と有効期限。",
			"abt.featTitle": "Summit Linux の機能",
			"abt.goalLabel": "目標:",
			"abt.goalText":
				"最小で監査可能なベースを、どのマシンでもゼロから再構築できること。",
			"abt.intro":
				"Summit Linux は Linux From Scratch の原則に従い、ソースからビルドされる独立した Linux ディストリビューションです。",
			"abt.li.1": "コンパイルフラグを完全に制御。",
			"abt.li.2": "不要なソフトウェアは最小限。",
			"abt.li.3": "宣言的なパッケージレシピ。",
			"abt.li.4": "再現可能で検証可能なビルド。",
			"abt.li.5": "暗号学的に検証されたリポジトリ。",
			"abt.li.6": "安定して予測可能なシステム動作。",
			"abt.missionP":
				"経験豊富なユーザーに完全に説明できるシステムを:すべてのバイナリは読みやすいレシピにたどり着き、すべてのリポジトリインデックスは検証可能な署名を持ち、求められていないものは何も入りません。",
			"abt.philoLabel": "理念:",
			"abt.philoText":
				"魔法ではなく透明性を、ブラックボックスではなくレシピを。",
			"abt.rm.1t": "ベースシステム (LFS ツールチェーン)",
