			"wiki.faq5q": "Kann ich Pakete aus Quellen bauen?",
			"wiki.faq5a":
				"Ja — <code>picu cook</code> mit einer Rezeptdatei baut isoliert und reproduzierbar.",
			"wiki.faq6q": "Wo ist die vollständige Dokumentation?",
			"wiki.faq6a":
				'Im <a href=\\"https://github.com/Summit-picu/Markdown-files-and-info\\" target=\\"_blank\\" rel=\\"noopener\\">Markdown-files-and-info</a>-Repo und auf der <a href=\\"download.html\\">Download</a>-Seite.',
