			"abt.feat.3": "Init nach Wahl: OpenRC / sysvinit mit optionalem runit.",
			"abt.feat.4":
				"Reproduzierbare Builds: feste Flags, isolierte Build-Umgebung, Checksummen der Quellen.",
			"abt.feat.5":
				"Alles signiert: Repository-Indizes, Releases und Rezepte werden kryptografisch verifiziert.",
			"abt.feat.6":
				"Downgrade-Schutz: Versionsprüfungen und Ablaufdaten der Repository-Metadaten.",
			"abt.featTitle": "Summit-Linux-Funktionen",
			"abt.goalLabel": "Ziel:",
			"abt.goalText":
				"eine minimale, prüfbare Basis, die man auf jeder Maschine von Grund auf neu bauen kann.",
			"abt.intro":
				"Summit Linux ist eine unabhängige Linux-Distribution, die nach den Prinzipien von Linux From Scratch aus dem Quellcode gebaut wird.",
			"abt.li.1": "Volle Kontrolle über Compiler-Flags.",
			"abt.li.2": "Minimale überflüssige Software.",
			"abt.li.3": "Deklarative Paketrezepte.",
			"abt.li.4": "Reproduzierbare und überprüfbare Builds.",
			"abt.li.5": "Kryptografisch verifizierte Repositories.",
			"abt.li.6": "Stabiles und vorhersehbares Systemverhalten.",
			"abt.missionP":
				"Erfahrenen Nutzern ein System geben, das sie vollständig erklären können: Jedes Binary lässt sich auf ein lesbares Rezept zurückführen, jeder Repository-Index trägt eine überprüfbare Signatur, und nichts wird installiert, worum der Nutzer nicht gebeten hat.",
			"abt.philoLabel": "Philosophie:",
