			"idx.statusText":
				"Summit Linux est un concept de distribution indépendante LFS/source avec <code>picu</code> comme gestionnaire de paquets. La documentation définit le modèle de confiance, le modèle de transactions, l’isolation des builds et le plan par étapes.",
			"wiki.title": "Wiki Summit Linux",
			"wiki.lead":
				"Documentation communautaire sur Summit Linux et le gestionnaire picu : concepts, commandes, dépôts et réponses.",
			"wiki.secWhat": "Qu’est-ce que Summit Linux",
			"wiki.secInstall": "Installation",
			"wiki.secQuick": "Démarrage rapide",
			"wiki.secCommands": "Commandes",
