			"wiki.secFaq": "Questions fréquentes",
			"wiki.secLinks": "Liens",
			"wiki.whatText":
				"Summit Linux est une distribution Linux indépendante compilée depuis les sources selon les principes Linux From Scratch : composants transparents, builds contrôlés et logiciel minimal.",
			"wiki.philoLabel": "Philosophie :",
			"wiki.philoText":
				"la transparence plutôt que la magie, une recette plutôt qu’une boîte noire.",
			"wiki.installNote":
				"Cette section est en développement — bientôt disponible.",
			"wiki.quickText":
				"Le quotidien en trois commandes : synchroniser les index, installer un paquet, mettre à jour le système.",
			"wiki.cmdText":
				"picu gère les dépôts, recettes de build, paquets binaires, signatures, magasins de confiance et la base des paquets.",
			"wiki.cmdSync":
				"— récupérer les index des dépôts et vérifier les signatures.",
			"wiki.cmdAdd": "— installer un paquet depuis un miroir de confiance.",
			"wiki.cmdCook": "— compiler un paquet depuis les sources en isolation.",
			"wiki.cmdCut": "— supprimer un paquet et nettoyer les restes.",
			"wiki.cmdFind": "— rechercher des paquets dans les index.",
			"wiki.cmdList": "— afficher les paquets installés.",
			"wiki.cmdInfo": "— afficher version, recette et détails du miroir.",
			"wiki.cmdUpdate":
				"— mettre à jour vers les dernières versions de confiance.",
			"wiki.cmdRebase":
				"— reconstruire une recette locale sur la base actuelle.",
			"wiki.cmdTrust":
				"— afficher les clés de confiance et certificats révoqués.",
			"wiki.mirrorsNoteLabel": "Miroirs communautaires :",
			"wiki.mirrorsNoteText":
				"ils exigent une confiance explicite — n’activez jamais un miroir non fiable avec des options non sûres sur un système de production.",
			"wiki.faq1q": "Summit Linux est-il prêt pour un usage quotidien ?",
			"wiki.faq1a":
				"Le projet est un concept fonctionnel avec un plan par étapes ; suivez la page des nouvelles pour les versions.",
			"wiki.faq2q": "En quoi picu diffère-t-il des autres gestionnaires ?",
			"wiki.faq2a":
				"picu combine recettes source et paquets binaires avec vérification cryptographique de chaque index.",
			"wiki.faq3q": "Quel système d’init Summit utilise-t-il ?",
			"wiki.faq3a":
				"OpenRC / sysvinit avec une configuration runit optionnelle.",
			"wiki.faq4q": "Comment vérifier les téléchargements ?",
			"wiki.faq4a":
				"Les versions auront des sommes de contrôle et les index seront signés ; voir la page de téléchargement.",
			"wiki.faq5q": "Puis-je compiler des paquets depuis les sources ?",
			"wiki.faq5a":
				"Oui — <code>picu cook</code> avec un fichier recette pour un build isolé et reproductible.",
			"wiki.faq6q": "Où est la documentation complète ?",
			"wiki.faq6a":
				'Dans le dépôt <a href=\\"https://github.com/Summit-picu/Markdown-files-and-info\\" target=\\"_blank\\" rel=\\"noopener\\">Markdown-files-and-info</a> et sur la page <a href=\\"download.html\\">Téléchargement</a>.',
			"wiki.faq7q": "Quelles commandes picu vais-je utiliser le plus ?",
			"wiki.faq7a":
				"<code>picu sync</code>, <code>picu add</code>, <code>picu update</code>, <code>picu find</code> et <code>picu info</code> au quotidien ; <code>picu cook</code> et <code>picu cut</code> pour les sources ; <code>picu trust</code> pour les clés.",
			"wiki.faq8q": "Comment ajouter un miroir communautaire ?",
			"wiki.faq8a":
				"Ajoutez sa description dans <code>/etc/picu/mirrors.d/</code> et accordez-lui une confiance explicite — jamais de confiance par défaut.",
			"wiki.faq9q": "Que faire si une vérification de signature échoue ?",
			"wiki.faq9a":
				"N’installez rien : relancez <code>picu sync</code>, vérifiez l’expiration de l’index et vos clés, puis signalez le miroir.",
