			"wiki.secLinks": "Linki",
			"wiki.whatText":
				"Summit Linux to niezależna dystrybucja Linuksa budowana ze źródeł według zasad Linux From Scratch: przejrzyste komponenty, kontrolowane kompilacje i minimum oprogramowania.",
			"wiki.philoLabel": "Filozofia:",
			"wiki.philoText":
				"przejrzystość zamiast magii, przepis zamiast czarnej skrzynki.",
			"wiki.installNote": "Ta sekcja jest w przygotowaniu — wkrótce.",
			"wiki.quickText":
				"Codzienna praca w trzech poleceniach: synchronizuj indeksy, zainstaluj pakiet, zaktualizuj system.",
			"wiki.cmdText":
				"picu zarządza repozytoriami, przepisami kompilacji, pakietami binarnymi, podpisami, magazynem zaufania i bazą pakietów.",
			"wiki.cmdSync": "— pobierz indeksy repozytoriów i zweryfikuj podpisy.",
			"wiki.cmdAdd": "— zainstaluj pakiet z zaufanego lustra.",
			"wiki.cmdCook": "— zbuduj pakiet ze źródeł w izolacji.",
			"wiki.cmdCut": "— usuń pakiet i posprzątaj pozostałości.",
			"wiki.cmdFind": "— szukaj pakietów w indeksach repozytoriów.",
			"wiki.cmdList": "— pokaż zainstalowane pakiety.",
			"wiki.cmdInfo": "— pokaż wersję, przepis i szczegóły lustra.",
			"wiki.cmdUpdate":
				"— zaktualizuj pakiety do najnowszych zaufanych wersji.",
			"wiki.cmdRebase": "— przebuduj lokalny przepis na aktualnej bazie.",
			"wiki.cmdTrust": "— pokaż zaufane klucze i unieważnione certyfikaty.",
			"wiki.mirrorsNoteLabel": "Lustra społeczności:",
			"wiki.mirrorsNoteText":
				"wymagają jawnego zaufania — nigdy nie włączaj niezaufanego lustra z niebezpiecznymi flagami na systemie produkcyjnym.",
			"wiki.faq1q": "Czy Summit Linux nadaje się do codziennego użytku?",
			"wiki.faq1a":
				"Projekt to działająca koncepcja z planem etapowym; śledź stronę aktualności.",
			"wiki.faq2q": "Czym picu różni się od innych menedżerów pakietów?",
			"wiki.faq2a":
				"picu łączy przepisy źródłowe i pakiety binarne z kryptograficzną weryfikacją każdego indeksu.",
			"wiki.faq3q": "Jakiego systemu init używa Summit?",
			"wiki.faq3a": "OpenRC / sysvinit z opcjonalną konfiguracją runit.",
			"wiki.faq4q": "Jak weryfikować pobrane pliki?",
			"wiki.faq4a":
				"Wydania będą miały sumy kontrolne, a indeksy będą podpisane; szczegóły na stronie pobierania.",
			"wiki.faq5q": "Czy mogę budować pakiety ze źródeł?",
			"wiki.faq5a":
				"Tak — <code>picu cook</code> z plikiem przepisu dla izolowanej, powtarzalnej kompilacji.",
			"wiki.faq6q": "Gdzie jest pełna dokumentacja?",
			"wiki.faq6a":
				'W repozytorium <a href=\\"https://github.com/Summit-picu/Markdown-files-and-info\\" target=\\"_blank\\" rel=\\"noopener\\">Markdown-files-and-info</a> i na stronie <a href=\\"download.html\\">pobierania</a>.',
			"wiki.faq7q": "Jakich poleceń picu będę używać najczęściej?",
			"wiki.faq7a":
				"<code>picu sync</code>, <code>picu add</code>, <code>picu update</code>, <code>picu find</code> i <code>picu info</code> na co dzień; <code>picu cook</code> i <code>picu cut</code> do źródeł; <code>picu trust</code> do kluczy.",
			"wiki.faq8q": "Jak dodać lustro społeczności?",
			"wiki.faq8a":
				"Dodaj jego opis do <code>/etc/picu/mirrors.d/</code> i nadaj jawne zaufanie — lustra społeczności nigdy nie są domyślnie zaufane.",
			"wiki.faq9q": "Co jeśli weryfikacja podpisu się nie powiedzie?",
			"wiki.faq9a":
				"Niczego nie instaluj: powtórz <code>picu sync</code>, sprawdź ważność indeksu i zaufane klucze, potem zgłoś lustro.",
			"wiki.linksDownload": "Pobierz Summit Linux",
			"wiki.linksDocs": "Repozytorium dokumentacji Markdown-files-and-info",
