			"abt.baseP":
				"Summit jest skierowany do doświadczonych użytkowników Linuksa i opiera się na modelu LFS/budowania ze źródeł.",
			"abt.feat.1":
				"Źródła przede wszystkim: toolchain LFS i deklaratywne przepisy kompilacji.",
			"abt.feat.2":
				"Minimalna baza: domyślna instalacja tylko z CLI, bez ukrytych usług.",
			"abt.feat.3": "Init do wyboru: OpenRC / sysvinit z opcjonalnym runit.",
			"abt.feat.4":
				"Odtwarzalne kompilacje: stałe flagi, izolowane środowisko, sumy kontrolne źródeł.",
			"abt.feat.5":
				"Wszystko podpisane: indeksy repozytoriów, wydania i przepisy weryfikowane kryptograficznie.",
			"abt.feat.6":
				"Ochrona przed wycofaniem: sprawdzanie wersji i terminów metadanych repozytoriów.",
			"abt.featTitle": "Możliwości Summit Linux",
			"abt.goalLabel": "Cel:",
			"abt.goalText":
				"minimalna, audytowalna baza, którą można odbudować od zera na każdej maszynie.",
			"abt.intro":
				"Summit Linux to niezależna dystrybucja Linuksa budowana ze źródeł zgodnie z zasadami Linux From Scratch.",
			"abt.li.1": "Pełna kontrola nad flagami kompilacji.",
			"abt.li.2": "Minimum zbędnego oprogramowania.",
			"abt.li.3": "Deklaratywne przepisy pakietów.",
			"abt.li.4": "Odtwarzalne i weryfikowalne kompilacje.",
			"abt.li.5": "Kryptograficznie weryfikowane repozytoria.",
			"abt.li.6": "Stabilne i przewidywalne zachowanie systemu.",
			"abt.missionP":
				"Dać doświadczonym użytkownikom system, który da się w pełni wyjaśnić: każdy plik binarny wywodzi się z czytelnego przepisu, każdy indeks repozytorium niesie weryfikowalny podpis i nic nie instaluje się bez wiedzy użytkownika.",
