			"wiki.faq1q": "क्या Summit Linux रोज़मर्रा के लिए तैयार है?",
			"wiki.faq1a":
				"यह चरणबद्ध योजना वाला कार्यशील विचार है; रिलीज़ हेतु समाचार पृष्ठ देखें।",
			"wiki.faq2q": "picu अन्य प्रबंधकों से कैसे अलग है?",
			"wiki.faq2a":
				"picu स्रोत रेसिपी और बाइनरी पैकेज को हर इंडेक्स के क्रिप्टो सत्यापन से जोड़ता है।",
			"wiki.faq3q": "Summit कौन-सा init उपयोग करता है?",
			"wiki.faq3a": "वैकल्पिक runit सेटअप के साथ OpenRC / sysvinit।",
			"wiki.faq4q": "डाउनलोड कैसे सत्यापित करूँ?",
			"wiki.faq4a": "रिलीज़ में चेकसम और इंडेक्स में हस्ताक्षर होंगे; विवरण डाउनलोड पृष्ठ पर।",
			"wiki.faq5q": "क्या स्रोत से पैकेज बना सकता हूँ?",
			"wiki.faq5a":
				"हाँ — अलग, पुनरुत्पादनीय बिल्ड हेतु रेसिपी फ़ाइल से <code>picu cook</code>।",
			"wiki.faq6q": "पूर्ण दस्तावेज़ कहाँ है?",
			"wiki.faq6a":
				'<a href=\\"https://github.com/Summit-picu/Markdown-files-and-info\\" target=\\"_blank\\" rel=\\"noopener\\">Markdown-files-and-info</a> रिपो और <a href=\\"download.html\\">डाउनलोड</a> पृष्ठ पर।',
			"wiki.faq7q": "कौन-से picu कमांड सबसे ज़्यादा काम आएँगे?",
			"wiki.faq7a":
				"रोज़ <code>picu sync</code>, <code>picu add</code>, <code>picu update</code>, <code>picu find</code> और <code>picu info</code>; स्रोत हेतु <code>picu cook</code> व <code>picu cut</code>; कुंजियों हेतु <code>picu trust</code>।",
			"wiki.faq8q": "सामुदायिक मिरर कैसे जोड़ूँ?",
			"wiki.faq8a":
				"विवरण <code>/etc/picu/mirrors.d/</code> में जोड़ें और स्पष्ट भरोसा दें — मिरर डिफ़ॉल्ट भरोसेमंद नहीं होते।",
			"wiki.faq9q": "हस्ताक्षर जाँच विफल हो तो?",
			"wiki.faq9a":
				"कुछ न लगाएँ: <code>picu sync</code> दोहराएँ, इंडेक्स समाप्ति व कुंजियाँ जाँचें, फिर मिरर रिपोर्ट करें।",
			"wiki.linksDownload": "Summit Linux डाउनलोड करें",
			"wiki.linksDocs": "Markdown-files-and-info दस्तावेज़ रिपो",
