				"Summit Linux adalah distro Linux independen yang dibangun dari sumber mengikuti prinsip Linux From Scratch: komponen transparan, build terkendali, dan perangkat lunak minimal.",
			"wiki.philoLabel": "Filosofi:",
			"wiki.philoText": "transparansi bukan sulap, resep bukan kotak hitam.",
			"wiki.installNote": "Bagian ini dalam pengembangan — segera hadir.",
			"wiki.quickText":
				"Kerja harian dalam tiga perintah: sinkron indeks, pasang paket, perbarui sistem.",
			"wiki.cmdText":
				"picu mengelola repositori, resep build, paket biner, tanda tangan, trust store, dan basis data paket.",
			"wiki.cmdSync": "— ambil indeks repositori dan verifikasi tanda tangan.",
			"wiki.cmdAdd": "— pasang paket dari mirror tepercaya.",
			"wiki.cmdCook": "— bangun paket dari sumber secara terisolasi.",
			"wiki.cmdCut": "— hapus paket dan bersihkan sisa.",
			"wiki.cmdFind": "— cari paket di indeks.",
			"wiki.cmdList": "— tampilkan paket terpasang.",
			"wiki.cmdInfo": "— tampilkan versi, resep, dan detail mirror.",
			"wiki.cmdUpdate": "— perbarui ke versi tepercaya terbaru.",
			"wiki.cmdRebase": "— bangun ulang resep lokal di basis saat ini.",
			"wiki.cmdTrust": "— tampilkan kunci tepercaya dan sertifikat dicabut.",
			"wiki.mirrorsNoteLabel": "Mirror komunitas:",
			"wiki.mirrorsNoteText":
				"butuh kepercayaan eksplisit — jangan aktifkan mirror tak tepercaya dengan flag tak aman di produksi.",
			"wiki.faq1q": "Apakah Summit Linux siap harian?",
			"wiki.faq1a":
				"Proyek ini konsep berjalan dengan rencana bertahap; ikuti halaman Berita untuk rilis.",
			"wiki.faq2q": "Apa beda picu dengan manajer lain?",
			"wiki.faq2a":
				"picu menggabungkan resep sumber dan paket biner dengan verifikasi kriptografis tiap indeks.",
			"wiki.faq3q": "Init apa yang dipakai Summit?",
			"wiki.faq3a": "OpenRC / sysvinit dengan setup runit opsional.",
			"wiki.faq4q": "Bagaimana verifikasi unduhan?",
			"wiki.faq4a":
				"Rilis akan ada checksum dan indeks akan ditandatangani; lihat halaman Unduh.",
			"wiki.faq5q": "Bisa membangun paket dari sumber?",
			"wiki.faq5a":
				"Ya — <code>picu cook</code> dengan file resep untuk build terisolasi dan reproduksibel.",
			"wiki.faq6q": "Di mana dokumentasi lengkap?",
			"wiki.faq6a":
				'Di repo <a href=\\"https://github.com/Summit-picu/Markdown-files-and-info\\" target=\\"_blank\\" rel=\\"noopener\\">Markdown-files-and-info</a> dan halaman <a href=\\"download.html\\">Unduh</a>.',
			"wiki.faq7q": "Perintah picu apa yang paling sering dipakai?",
			"wiki.faq7a":
				"Harian <code>picu sync</code>, <code>picu add</code>, <code>picu update</code>, <code>picu find</code> dan <code>picu info</code>; sumber <code>picu cook</code> dan <code>picu cut</code>; kunci <code>picu trust</code>.",
			"wiki.faq8q": "Bagaimana menambah mirror komunitas?",
			"wiki.faq8a":
				"Tambahkan deskripsinya di <code>/etc/picu/mirrors.d/</code> dan beri kepercayaan eksplisit — mirror komunitas tak pernah tepercaya default.",
			"wiki.faq9q": "Jika verifikasi tanda gagal?",
			"wiki.faq9a":
				"Jangan pasang apa pun: ulangi <code>picu sync</code>, cek kedaluwarsa indeks dan kuncimu, lalu laporkan mirrornya.",
			"wiki.linksDownload": "Unduh Summit Linux",
			"wiki.linksDocs": "Repo dokumen Markdown-files-and-info",
