				"Summit Linux là ý tưởng distro độc lập LFS/từ nguồn với <code>picu</code> làm quản lý gói. Tài liệu định nghĩa mô hình tin cậy, mô hình giao dịch, cách ly bản dựng và kế hoạch theo giai đoạn.",
			"wiki.title": "Wiki Summit Linux",
