				"cần tin cậy rõ ràng — đừng bật mirror không tin cậy với cờ kém an toàn trên hệ production.",
			"wiki.faq1q": "Summit Linux đã dùng hằng ngày được chưa?",
			"wiki.faq1a":
				"Dự án là ý tưởng đang chạy với kế hoạch theo giai đoạn; theo dõi trang Tin tức để biết bản phát hành.",
