			"wiki.secLinks": "링크",
			"wiki.whatText":
				"Summit Linux는 Linux From Scratch 원칙으로 소스에서 빌드한 독립 배포판입니다: 투명한 구성 요소, 통제된 빌드, 최소 소프트웨어.",
			"wiki.philoLabel": "철학:",
			"wiki.philoText": "마법 대신 투명성, 블랙박스 대신 레시피.",
			"wiki.installNote": "이 절은 개발 중 — 곧 공개.",
			"wiki.quickText":
				"일상 작업은 세 명령으로: 인덱스 동기화, 패키지 설치, 시스템 업그레이드.",
			"wiki.cmdText":
				"picu는 저장소, 빌드 레시피, 바이너리 패키지, 서명, 신뢰 저장소, 패키지 DB를 관리합니다.",
			"wiki.cmdSync": "— 저장소 인덱스를 가져오고 서명을 검증.",
			"wiki.cmdAdd": "— 신뢰 미러에서 패키지 설치.",
			"wiki.cmdCook": "— 격리 환경에서 소스로 빌드.",
			"wiki.cmdCut": "— 패키지를 제거하고 잔여물 정리.",
			"wiki.cmdFind": "— 인덱스에서 패키지 검색.",
			"wiki.cmdList": "— 설치된 패키지 표시.",
			"wiki.cmdInfo": "— 버전, 레시피, 미러 상세 표시.",
			"wiki.cmdUpdate": "— 최신 신뢰 버전으로 업그레이드.",
			"wiki.cmdRebase": "— 현재 베이스에 로컬 레시피 재빌드.",
			"wiki.cmdTrust": "— 신뢰 키와 취소된 인증서 표시.",
			"wiki.mirrorsNoteLabel": "커뮤니티 미러:",
			"wiki.mirrorsNoteText":
				"명시적 신뢰가 필요합니다 — 프로덕션에서 불안전한 플래그로 미신뢰 미러를 활성화하지 마세요.",
			"wiki.faq1q": "Summit Linux를 일상적으로 쓸 수 있나요?",
			"wiki.faq1a":
				"단계별 계획이 있는 동작 중인 구상입니다. 릴리스는 News 페이지를 참조하세요.",
			"wiki.faq2q": "picu는 다른 관리자와 어떻게 다르죠?",
			"wiki.faq2a":
				"picu는 소스 레시피와 바이너리를 결합하고 모든 인덱스를 암호학적으로 검증합니다.",
			"wiki.faq3q": "Summit의 init은?",
			"wiki.faq3a": "OpenRC / sysvinit, 선택적 runit 구성.",
			"wiki.faq4q": "다운로드를 검증하려면?",
			"wiki.faq4a":
				"릴리스에는 체크섬, 인덱스에는 서명이 붙습니다. Download 페이지를 보세요.",
			"wiki.faq5q": "소스에서 빌드할 수 있나요?",
			"wiki.faq5a":
				"예 — 레시피 파일로 <code>picu cook</code>를 써서 격리·재현 가능 빌드를 합니다.",
			"wiki.faq6q": "전체 문서는 어디에?",
			"wiki.faq6a":
				'<a href=\\"https://github.com/Summit-picu/Markdown-files-and-info\\" target=\\"_blank\\" rel=\\"noopener\\">Markdown-files-and-info</a> 저장소와 <a href=\\"download.html\\">Download</a> 페이지에 있습니다.',
			"wiki.faq7q": "자주 쓰는 picu 명령은?",
			"wiki.faq7a":
				"일상은 <code>picu sync</code>, <code>picu add</code>, <code>picu update</code>, <code>picu find</code>, <code>picu info</code>. 소스용 <code>picu cook</code>·<code>picu cut</code>, 키 관리용 <code>picu trust</code>.",
			"wiki.faq8q": "커뮤니티 미러를 추가하려면?",
			"wiki.faq8a":
				"<code>/etc/picu/mirrors.d/</code>에 설명을 추가하고 명시적으로 신뢰하세요 — 기본 신뢰는 없습니다.",
			"wiki.faq9q": "서명 검증이 실패하면?",
			"wiki.faq9a":
				"아무 것도 설치 말고 <code>picu sync</code>를 다시 실행하고 인덱스 만료와 키를 확인한 뒤 미러를 신고하세요.",
